                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append((color, cells))

    # Bounding boxes of substantial colored objects indicate where an
    # isolated overpainted pixel should be restored.
    boxes = []
    for color, cells in components:
        if len(cells) > 1:
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            boxes.append((color, min(rs), max(rs), min(cs), max(cs)))

    out = [row[:] for row in grid]
    for color, cells in components:
        if len(cells) == 1:
            r, c = cells[0]
            replacement = bg
            for obj_color, r0, r1, c0, c1 in boxes:
                if obj_color != color and r0 <= r <= r1 and c0 <= c <= c1:
                    replacement = obj_color
                    break
            out[r][c] = replacement
    return out
